BEGIN
CREATE TABLE [dbo].[didprog] (
iddidprog int NOT NULL,
idcorsostudio int NOT NULL,
aa varchar(9) NULL,
annosolare int NULL,
attribdebiti nvarchar(max) NULL,
ciclo int NULL,
codice varchar(50) NULL,
codicemiur varchar(50) NULL,
dataconsmaxiscr date NULL,
freqobbl char(1) NULL,
